  ('{title} is open again', '{title} ist wieder offen'),
  ('Only {share} of the plan – far off, but it counts as done. Feeling good? Add a bit on an easy day; otherwise just carry on.', 'Nur {share} des Plans – stark abweichend, zählt aber als erledigt. Fühlst du dich gut, ergänze etwas an einem lockeren Tag; sonst einfach weitermachen.'),
  ('partly done ({share})', 'teilweise erledigt ({share})'),
  ('done on {day}', 'erledigt am {day}'),
  ('before the plan', 'vor Planstart'),
  ('Workouts done', 'Einheiten erledigt'),
